Map<String, Integer> countByStage(List<Opportunity> opps) {
    Map<String, Integer> counts = new Map<String, Integer>();
    for (Opportunity o : opps) {
        Integer current = counts.get(o.StageName);
        counts.put(o.StageName, current == null ? 1 : current + 1);
    }
    return counts;
}
